"use strict";

function isoAt(base, dayOffset, hour, minute) {
  const date = new Date(base);
  const mondayOffset = (date.getDay() + 6) % 7;
  date.setDate(date.getDate() - mondayOffset + dayOffset);
  date.setHours(hour, minute || 0, 0, 0);
  return date.toISOString();
}

function demoAppointmentSnapshot(now) {
  const base = now || new Date();
  const rows = [
    ["apt-1", "Laura Gómez", "LG", "whatsapp", "confirmed", 0, 9, 0, 60, "Limpieza dental", "Paciente frecuente. Prefiere citas temprano.", "authorized"],
    ["apt-2", "Carlos Ruiz", "CR", "voice", "needs_you", 0, 11, 0, 45, "Valoración de ortodoncia", "El horario solicitado se cruzó con otra cita. La IA preparó dos alternativas.", "authorized"],
    ["apt-3", "Sofía Martínez", "SM", "whatsapp", "ai_confirming", 1, 10, 30, 60, "Diseño de sonrisa", "Quiere confirmar el valor y asistir el martes en la mañana.", "authorized"],
    ["apt-4", "Andrés Torres", "AT", "voice", "confirmed", 1, 15, 0, 45, "Consulta general", "Paciente nuevo. Reportó sensibilidad dental.", "authorized"],
    ["apt-5", "Mariana López", "ML", "whatsapp", "confirmed", 2, 8, 30, 60, "Blanqueamiento", "Confirmó por WhatsApp y recibió indicaciones previas.", "authorized"],
    ["apt-6", "Diego Pérez", "DP", "voice", "needs_you", 2, 14, 0, 60, "Urgencia odontológica", "Necesita una hora después de las 4 pm. Un mensaje tuyo cierra la cita.", "pending"],
    ["apt-7", "Valentina Díaz", "VD", "whatsapp", "confirmed", 3, 9, 30, 45, "Control de ortodoncia", "Paciente conocida. Control mensual.", "authorized"],
    ["apt-8", "Mateo Hernández", "MH", "voice", "ai_confirming", 3, 16, 0, 60, "Valoración infantil", "La IA espera confirmación del acudiente.", "authorized"],
    ["apt-9", "Natalia Romero", "NR", "whatsapp", "confirmed", 4, 10, 0, 60, "Limpieza dental", "Confirmó el recordatorio de 24 horas.", "authorized"],
    ["apt-10", "Felipe Castro", "FC", "voice", "confirmed", 4, 14, 30, 45, "Consulta general", "Agendada y sincronizada con Google Calendar.", "authorized"],
    ["apt-11", "Camila Rojas", "CR", "whatsapp", "ai_confirming", 5, 11, 0, 60, "Diseño de sonrisa", "Pidió información y eligió el sábado.", "authorized"]
  ].map(function (row, index) {
    return {
      id: row[0], conversation_id: row[0], tenant_id: "demo-clinica-sonrie", customer_name: row[1], initials: row[2],
      channel: row[3], ui_status: row[4], starts_at: isoAt(base, row[5], row[6], row[7]), duration_minutes: row[8],
      consultation_reason: row[9], transcript_summary: row[10], data_processing_consent: row[11],
      customer_phone: "+57 300 " + String(2148800 + index * 137), customer_email: row[1].toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/ /g, ".") + "@correo.com",
      previous_appointments: index % 4, alt_slots: ["Hoy · 4:30 pm", "Mañana · 9:00 am"], sync: row[4] === "confirmed" ? "synced" : "pending",
      transcript: [
        { from: "customer", text: "Hola, quisiera agendar una cita de " + row[9].toLowerCase() + "." },
        { from: "bot", text: "Claro. Ya revisé la agenda y recopilé tus datos para dejarla lista." }
      ]
    };
  });
  const reminders = [
    ["rem-1", "apt-3", "Sofía Martínez", "whatsapp", "programmed", "Hoy · 11:00 am", "24 h antes"],
    ["rem-2", "apt-6", "Diego Pérez", "voice", "programmed", "Hoy · 2:00 pm", "6 h antes"],
    ["rem-3", "apt-7", "Valentina Díaz", "whatsapp", "programmed", "Mañana · 9:30 am", "24 h antes"],
    ["rem-4", "apt-9", "Natalia Romero", "whatsapp", "confirmed", "Hace 1 h", "24 h antes"],
    ["rem-5", "apt-4", "Andrés Torres", "voice", "read", "Hace 2 h", "6 h antes"],
    ["rem-6", "apt-2", "Carlos Ruiz", "whatsapp", "no_response", "Ayer", "24 h antes"]
  ].map(function (row) { return { id: row[0], appointment_id: row[1], customer_name: row[2], channel: row[3], status: row[4], timing: row[5], offset: row[6] }; });
  return {
    ok: true,
    tenant_id: "demo-clinica-sonrie",
    business: { name: "Clínica Dental Sonríe", timezone: "America/Bogota" },
    source: "demo",
    provider: { id: "google_calendar", label: "Google Calendar · Dra. Rincón", status: "ready" },
    metrics: { interactions: rows.length, requested: rows.length, booked: rows.filter(function (row) { return row.ui_status === "confirmed"; }).length, pending: rows.filter(function (row) { return row.ui_status !== "confirmed"; }).length, confirmation_rate: 87, avoided_absences: 14, sent_reminders: 128 },
    appointments: rows,
    reminders: reminders
  };
}

function customerAppointmentSnapshot(snapshot, business) {
  snapshot = snapshot || {};
  const appointments = (snapshot.appointments || []).map(function (row) {
    const statusMap = { booked: "confirmed", rescheduled: "confirmed", requested: "ai_confirming", failed: "needs_you", cancelled: "cancelled" };
    return Object.assign({}, row, {
      id: row.conversation_id,
      ui_status: statusMap[row.status] || "ai_confirming",
      duration_minutes: Number(row.duration_minutes) || 60,
      initials: String(row.customer_name || "Cliente").split(/\s+/).slice(0, 2).map(function (part) { return part.charAt(0); }).join("").toUpperCase(),
      sync: row.sync || (row.calendar_sync_status === "synced" ? "synced" : "pending"),
      alt_slots: row.alt_slots || []
    });
  });
  return {
    ok: true,
    tenant_id: snapshot.tenant_id,
    business: business || null,
    source: snapshot.source || "memory",
    provider: { id: "google_calendar", label: "Google Calendar", status: "available" },
    metrics: Object.assign({ confirmation_rate: 0, avoided_absences: 0, sent_reminders: 0 }, snapshot.metrics || {}),
    appointments: appointments,
    reminders: snapshot.reminders || []
  };
}

