function appointmentRowMarkup(row){var id=row.id||row.conversation_id,status=apptStatus(row);return '<button class="apptRow '+status+'" data-id="'+attr(id)+'" onclick="openAppointment(this.dataset.id)"><span class="apptAvatar">'+esc(apptInitials(row))+'</span><span><strong>'+esc(row.customer_name||"Cliente")+'</strong><p>'+esc(apptTime(row)+' · '+(row.consultation_reason||"Cita")+' · '+apptChannel(row))+'</p></span><span class="apptStatusDot '+status+'" title="'+apptStatusLabel(status)+'"></span></button>';}
