function confirmAppointment(id){var row=appointmentById(id);if(!row)return;appointmentAction("confirm",id,null,"Cita confirmada en Nextfor ✓");}
function cancelAppointment(id){var row=appointmentById(id);if(!row||!window.confirm("¿Cancelar esta cita?"))return;appointmentAction("cancel",id,{reason:"Cancelada desde el panel"},"Cita cancelada y guardada ✓");}
function appointmentChatRowMarkup(row){var id=row.id||row.conversation_id,status=apptStatus(row);return '<button class="apptRow '+status+'" data-id="'+attr(id)+'" onclick="openAppointmentChat(this.dataset.id)"><span class="apptAvatar">'+esc(apptInitials(row))+'</span><span><strong>'+esc(row.customer_name||"Cliente")+'</strong><p>'+esc(apptTime(row)+' · '+(row.consultation_reason||"Cita")+' · '+apptChannel(row))+'</p></span><span class="apptStatusDot '+status+'" title="'+apptStatusLabel(status)+'"></span></button>';}
function openAppointmentChat(id){state.selectedAppointment=id;document.getElementById("apptChats").classList.add("detail-open");renderAppointmentChats();}
function closeAppointmentChat(){document.getElementById("apptChats").classList.remove("detail-open");}
