function confirmAppointmentReprogram(){var day=state.reprogramDay,rows=appointmentRows().filter(function(row){return apptDayIndex(row)===day&&apptStatus(row)!=="cancelled";}),ids=rows.map(function(row){return row.id||row.conversation_id;});closeAppointmentReprogram();appointmentAction("reprogram",ids,{reason:"Bloqueo de agenda desde el panel",message:"El usuario Nextfor solicitó reprogramar estas citas y ofrecer disculpas."},"Reprogramación guardada para seguimiento ✓");}
function appointmentToast(message){var toast=document.getElementById("apptToast");toast.textContent=message;toast.classList.add("show");setTimeout(function(){toast.classList.remove("show");},2600);}
